// Integration checks against the project generated by ios:prepare. Ruby and
// xcodeproj are required, but no Xcode, real profiles or signing keys are used.
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { cpSync, mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { tmpdir } from "node:os";
import { basename, dirname, join, resolve } from "node:path";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

const mobile = fileURLToPath(new URL("../", import.meta.url));
const require = createRequire(import.meta.url);
const { checkAppId } = require("../node_modules/@capacitor/cli/dist/common.js");
const { loadConfig } = require("../node_modules/@capacitor/cli/dist/config.js");
const run = (cwd, script, ...args) => spawnSync("ruby", [join(mobile, "scripts", script), ...args], {
  cwd, encoding: "utf8", env: { ...process.env, BUILD_NUMBER: "37" },
});
const success = (result) => assert.equal(result.status, 0, `${result.error ?? ""}\n${result.stdout}\n${result.stderr}`);
const ruby = (cwd, code) => {
  const result = spawnSync("ruby", ["-rxcodeproj", "-rjson", "-e", code], { cwd, encoding: "utf8" });
  success(result);
  return result.stdout;
};
const fixture = (t) => {
  const cwd = mkdtempSync(join(tmpdir(), "kakomon-ios-test-"));
  assert.equal(dirname(resolve(cwd)), resolve(tmpdir()));
  assert.ok(basename(cwd).startsWith("kakomon-ios-test-"));
  t.after(() => rmSync(cwd, { recursive: true, force: true }));
  // Copy just the App project/metadata, never Pods or the web asset bundle.
  const native = join(cwd, "ios/App/App");
  mkdirSync(join(native, "Base.lproj"), { recursive: true });
  cpSync(join(mobile, "ios/App/App.xcodeproj"), join(cwd, "ios/App/App.xcodeproj"), { recursive: true });
  for (const file of ["Info.plist", "capacitor.config.json", "Base.lproj/Main.storyboard"]) {
    cpSync(join(mobile, "ios/App/App", file), join(native, file));
  }
  success(run(cwd, "configure-ios.rb"));
  return cwd;
};
const editSetting = (cwd, name, value, configuration = "Release") => ruby(cwd, `
  project = Xcodeproj::Project.open('ios/App/App.xcodeproj')
  config = project.targets.find { |t| t.name == 'App' }.build_configurations.find { |c| c.name == ${JSON.stringify(configuration)} }
  config.build_settings[${JSON.stringify(name)}] = ${JSON.stringify(value)}
  project.save
`);
const rejects = (cwd, message, ...args) => {
  const result = run(cwd, "verify-ios.rb", ...args);
  assert.notEqual(result.status, 0);
  assert.match(result.stderr, message);
};

test("the pinned CLI accepts the generation ID and rejects the registered Apple ID", async () => {
  const config = await loadConfig();
  assert.equal(config.app.appId, "jp.kakomonai.app");
  assert.equal(await checkAppId(config, config.app.appId), null);
  assert.match(await checkAppId(config, "jp.kakomon-ai.app"), /Invalid App ID/);
});

test("configuration restores every App build configuration and is idempotent", (t) => {
  const cwd = fixture(t);
  success(run(cwd, "verify-ios.rb"));
  const file = join(cwd, "ios/App/App.xcodeproj/project.pbxproj");
  const before = readFileSync(file, "utf8");
  success(run(cwd, "configure-ios.rb"));
  assert.equal(readFileSync(file, "utf8"), before);
  editSetting(cwd, "PRODUCT_BUNDLE_IDENTIFIER", "jp.kakomonai.app", "Debug");
  editSetting(cwd, "PRODUCT_BUNDLE_IDENTIFIER", "jp.kakomonai.app", "Release");
  success(run(cwd, "configure-ios.rb"));
  success(run(cwd, "verify-ios.rb"));
});

for (const configuration of ["Debug", "Release"]) {
  test(`verification rejects a different Bundle ID in ${configuration}`, (t) => {
    const cwd = fixture(t);
    editSetting(cwd, "PRODUCT_BUNDLE_IDENTIFIER", "jp.kakomonai.app", configuration);
    rejects(cwd, new RegExp(`Bundle ID mismatch in ${configuration}`));
  });
}

test("verification rejects a stale build number and runtime ID from cap sync", (t) => {
  const cwd = fixture(t);
  editSetting(cwd, "CURRENT_PROJECT_VERSION", "1");
  rejects(cwd, /Build number mismatch/);
  success(run(cwd, "configure-ios.rb"));
  const file = join(cwd, "ios/App/App/capacitor.config.json");
  const config = JSON.parse(readFileSync(file, "utf8"));
  config.appId = "jp.kakomonai.app";
  writeFileSync(file, JSON.stringify(config));
  rejects(cwd, /runtime Bundle ID mismatch/);
});

test("verification rejects a literal Info.plist Bundle ID", (t) => {
  const cwd = fixture(t);
  ruby(cwd, `path = 'ios/App/App/Info.plist'; p = Xcodeproj::Plist.read_from_path(path); p['CFBundleIdentifier'] = 'jp.kakomonai.app'; Xcodeproj::Plist.write_to_path(p, path)`);
  rejects(cwd, /Info.plist Bundle ID mismatch/);
});

test("export verification requires matching App Store profiles and applied signing settings", (t) => {
  const cwd = fixture(t);
  const options = join(cwd, "export.plist");
  const writeOptions = (id, method = "app-store-connect") => ruby(cwd, `
    Xcodeproj::Plist.write_to_path({'method' => ${JSON.stringify(method)}, 'provisioningProfiles' => {${JSON.stringify(id)} => 'fixture-profile'}}, 'export.plist')
  `);
  writeOptions("jp.kakomonai.app");
  rejects(cwd, /profile missing for registered Bundle ID/, options);
  writeOptions("jp.kakomon-ai.app", "development");
  rejects(cwd, /App Store export method required/, options);
  writeOptions("jp.kakomon-ai.app");
  rejects(cwd, /Signing team missing/, options);
  for (const configuration of ["Debug", "Release"]) {
    editSetting(cwd, "DEVELOPMENT_TEAM", "TESTTEAM01", configuration);
    editSetting(cwd, "CODE_SIGN_STYLE", "Manual", configuration);
    editSetting(cwd, "PROVISIONING_PROFILE_SPECIFIER", "fixture-profile", configuration);
  }
  success(run(cwd, "verify-ios.rb", options));
  editSetting(cwd, "PROVISIONING_PROFILE_SPECIFIER", "");
  rejects(cwd, /Provisioning profile missing/, options);
});

test("export verification also accepts Codemagic's Xcode-managed profile settings", (t) => {
  const cwd = fixture(t);
  ruby(cwd, `
    project = Xcodeproj::Project.open('ios/App/App.xcodeproj')
    target = project.targets.find { |t| t.name == 'App' }
    project.root_object.attributes['TargetAttributes'][target.uuid]['ProvisioningStyle'] = 'Automatic'
    target.build_configurations.each { |c| c.build_settings['DEVELOPMENT_TEAM'] = 'TESTTEAM01'; c.build_settings.delete('CODE_SIGN_STYLE'); c.build_settings.delete('PROVISIONING_PROFILE_SPECIFIER') }
    project.save
    Xcodeproj::Plist.write_to_path({'method' => 'app-store', 'provisioningProfiles' => {'jp.kakomon-ai.app' => 'fixture-profile'}}, 'export.plist')
  `);
  success(run(cwd, "verify-ios.rb", join(cwd, "export.plist")));
});
